import random

def gerar(n_ops, vars_, modo, seed=0):
    rnd = random.Random(seed)
    estado = {v: i for i, v in enumerate(vars_)}
    linhas = [f"{v} = {estado[v]}" for v in vars_]
    for _ in range(n_ops):
        a, b = rnd.sample(vars_, 2)
        if modo == 'reatribuir':
            k = rnd.randint(0, 9)
            linhas.append(f"{a} = {k}")
            estado[a] = k
        elif modo == 'acumular':
            k = rnd.randint(1, 5)
            linhas.append(f"{a} = {a} + {k}")
            estado[a] += k
        elif modo == 'referencia':
            linhas.append(f"{a} = {b}")
            estado[a] = estado[b]
    return "\n".join(linhas), estado
